// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Dünya kültürleri, gelenekler, bayramlar ve yemek kültürü (kolay).
const ozCulture1Kolay = <(String, String, List<String>, String)>[
  ('Nisan başında Tokyo\'daki bir parkta aileler pembe çiçek açmış ağaçların altına örtü serip yemek yiyor ve şarkı söylüyor. Bu manzara hangi Japon geleneğini yansıtır?', 'Hanami', ['Tanabata', 'Obon', 'Setsubun'], 'Hanami, "çiçek seyretme" anlamına gelir ve özellikle sakura (kiraz) çiçeklenmesi döneminde yapılır.'),
  ('Kyoto\'da bir çay töreninde ev sahibi, sıcak suyla karıştırdığı parlak yeşil tozu bambu bir çırpıcıyla köpürtüp konuğa sunuyor. Bu tören için kullanılan çay hangisidir?', 'Matcha', ['Sencha', 'Hojicha', 'Genmaicha'], 'Japon çay töreni (chanoyu) toz yeşil çay olan matcha ile yapılır; çay çasen adı verilen bambu çırpıcıyla çırpılır.'),
  ('Japonya\'da Şubat başında kutlanan Setsubun\'da evlerde kavrulmuş soya fasulyesi atılırken "Oni wa soto, fuku wa uchi" denir. Bu geleneğin amacı nedir?', 'Kötü ruhları kovup evi şansa açmak', ['Yeni hasadın bereketine topluca şükretmek', 'Atalara yiyecek sunmak', 'Yeni doğan çocukları kutlamak'], 'Söz "Şeytanlar dışarı, şans içeri" anlamına gelir; fasulye atma (mamemaki) kötülüğü uzaklaştırma ritüelidir.'),
  ('Ağustos ortasında Japonya\'ya giden bir öğrenci, insanların memleketlerine döndüğünü, mezarları ziyaret ettiğini ve akşamları meydanlarda halka olup dans ettiğini görüyor. Öğrenci hangi bayrama denk gelmiştir?', 'Obon', ['Shichi-Go-San', 'Hinamatsuri', 'Seijin no Hi'], 'Obon, ataların ruhlarını anma bayramıdır; sonunda ruhları uğurlamak için fenerler yakılır ya da suya bırakılır.'),
  ('Bir Japon aile 1 Ocak sabahı kalabalık bir Şinto tapınağında sıra bekleyip dua ediyor ve yeni yıl muskası alıyor. Ailenin yaptığı bu ziyaretin adı nedir?', 'Hatsumode', ['Hanami', 'Mamemaki', 'Tsukimi'], 'Hatsumode, yeni yılın ilk Şinto tapınağı ya da Budist tapınak ziyaretidir; insanlar yeni yıl için dua eder ve muska alır.'),
  ('Tokyo\'da bir lokantada önünüze sirke ve şekerle tatlandırılmış pirinç üzerine ince bir dilim ton balığı konmuş lokmalar geliyor. Size sunulan yemek hangisidir?', 'Suşi', ['Ramen', 'Tempura', 'Udon'], 'Suşi\'nin temeli sirke, şeker ve tuzla tatlandırılmış pirinçtir; balık her zaman bulunmaz ama yaygındır.'),
  ('Suşi ile saşimi arasındaki temel fark nedir?', 'Saşimide pirinç bulunmaz, yalnız ince dilimlenmiş çiğ balık vardır', ['Saşimi her zaman kızartılarak servis edilir', 'Saşimi yalnız tatlı su balıklarıyla ve pirinç üstünde yapılır', 'Saşimide balık yerine yalnız sebze kullanılır'], 'Saşimi pirinçsiz servis edilen ince dilimlenmiş çiğ balık ya da deniz ürünüdür; suşinin tanımlayıcı öğesi ise sirkeli pirinçtir.'),
  ('Sebze ya da deniz ürünlerinin hafif bir hamura bulanıp kızartılmasıyla yapılan ve Portekiz etkisiyle Japonya\'ya geldiği kabul edilen yemek hangisidir?', 'Tempura', ['Sukiyaki', 'Onigiri', 'Okonomiyaki'], 'Tempura 16. yüzyılda Portekizli misyoner ve tüccarların kızartma tekniğinden etkilenerek gelişmiştir.'),
  ('Bir Japon öğrenci okul gezisine giderken çantasına elle üçgen biçim verilmiş, nori yosununa sarılı ve içinde tuzlu erik bulunan pirinç lokmaları koyuyor. Bu yiyeceğin adı nedir?', 'Onigiri', ['Mochi', 'Gyoza', 'Takoyaki'], 'Onigiri, içine tuzlu erik ya da balık konabilen, elde biçimlendirilen pratik bir pirinç yemeğidir.'),
  ('Bir Japon ailesi yılbaşı gecesi uzun ve ince karabuğday eriştesi yiyor. Bu yemek hangi dileği simgeler?', 'Uzun bir ömür ve eski yılın kapanması', ['Bol yağmur yağması ve iyi bir pirinç hasadı', 'Yeni bir evlilik', 'Ticarette başarı'], 'Toshikoshi soba, yılı uğurlamak için yenir; uzun erişteler uzun ömrü, kolay kopmaları ise eski yılın sıkıntılarından kurtulmayı simgeler.'),
  ('Japon mutfağında fermente soya fasulyesinden yapılan, çorbası da yaygın olarak tüketilen ezmenin adı nedir?', 'Miso', ['Wasabi', 'Nori', 'Tofu'], 'Miso, soya fasulyesinin tuz ve koji küfü ile fermente edilmesiyle elde edilir; miso çorbası Japon sofrasının temel öğesidir.'),
  ('Pekin\'de çalışan biri ocak sonunda trenlerin aşırı kalabalık olduğunu, herkesin memleketine gittiğini ve kapılara kırmızı kâğıt süsler asıldığını görüyor. Hangi bayram yaklaşmaktadır?', 'Bahar Bayramı', ['Ay Ortası Festivali', 'Qingming Festivali', 'Ejderha Teknesi Festivali'], 'Bahar Bayramı (Çin Yeni Yılı) ay-güneş takvimine göre ocak sonu ile şubat ortası arasına denk gelir ve Çin\'in en önemli bayramıdır.'),
  ('Çin Yeni Yılı\'nda çocuklara ve gençlere içinde para bulunan kırmızı zarflar verilir. Kırmızı rengin seçilmesinin nedeni nedir?', 'Şansı ve kötülükten korunmayı simgelemesi', ['Yasın ve hüznün rengi olması', 'Göğü ve suyu simgelemesi', 'Toprağı ve hasadı temsil etmesi'], 'Çin kültüründe kırmızı şans, mutluluk ve kötü ruhları uzaklaştırmayla ilişkilidir; bu yüzden hongbao zarfları kırmızıdır.'),
  ('Çin Yeni Yılı\'nın on beşinci günü akşamı sokaklar kırmızı fenerlerle donatılıyor, insanlar fenerlere yazılmış bilmeceleri çözüyor ve tatlı pirinç topları yiyor. Bu bayram hangisidir?', 'Fener Festivali', ['Ay Ortası Festivali', 'Çifte Dokuz Festivali', 'Bahar Ekinoksu Festivali'], 'Fener Festivali (Yuanxiao) yeni yıl kutlamalarının son günüdür; fenerler asılır, bilmeceler çözülür ve tangyuan yenir.'),
  ('Eylül ortasında Şanghay\'da bir aile dolunayın altında toplanıp lotus tohumu ezmesiyle doldurulmuş, üzeri desenli yuvarlak çörekleri dilimleyip paylaşıyor. Paylaşılan yiyecek hangisidir?', 'Ay çöreği', ['Dim sum', 'Zongzi', 'Tangyuan'], 'Ay çöreği (yuebing) genellikle lotus tohumu ya da kırmızı fasulye ezmesiyle doldurulan yuvarlak bir çörektir; dolunay ve aile bütünlüğünü simgeler.'),
  ('Çin zodyağındaki on iki hayvanın sırası hangi hayvanla başlar?', 'Fare', ['Öküz', 'Kaplan', 'Ejderha'], 'Efsanedeki büyük yarışı fare, öküzün sırtına binip son anda atlayarak kazanır; bu yüzden döngü fareyle başlar.'),
  ('Hong Kong\'da bir aile pazar sabahı çay evine gidip bambu sepetlerde gelen küçük buharda mantılar ve çörekler sipariş ediyor. Ailenin katıldığı bu yemek geleneği hangisidir?', 'Dim sum', ['Hot pot', 'Chow mein', 'Mapo tofu'], 'Dim sum, Kanton\'daki "yum cha" (çay içme) geleneğiyle birlikte sunulan küçük porsiyon yemeklerdir.'),
  ('Ördeğin derisi çıtır olacak şekilde fırınlanıp ince krepler, taze soğan ve tatlı sosla servis edildiği ünlü Çin yemeği hangi kentin adını taşır?', 'Pekin', ['Şanghay', 'Kanton', 'Nanjing'], 'Pekin ördeği, imparatorluk döneminden beri başkentle özdeşleşmiş, ince krep içinde sarılarak yenen fırınlanmış ördektir.'),
  ('Chengdu\'da bir grup arkadaş, masanın ortasında kaynayan acılı et suyu kazanına çiğ et dilimleri, mantar ve erişte daldırarak kendi yemeklerini pişiriyor. Bu sofra geleneği hangisidir?', 'Hot pot', ['Kung pao', 'Char siu', 'Wonton'], 'Hot pot (huoguo) paylaşılan bir kaynar et suyu kazanında malzemelerin masada pişirildiği ortak bir yemek biçimidir.'),
  ('Çin\'de doğum günlerinde uzun erişte yenir ve erişteler kesilmeden pişirilir. Bu uygulama neyi simgeler?', 'Uzun ömrü', ['Zenginliği', 'Yeni bir başlangıcı', 'Aile birliğini'], 'Uzun ömür eriştesi (changshou mian) uzun ömür dileğini temsil eder; eriştenin kesilmesi ömrün kısalması olarak yorumlanır.'),
  ('Seul\'deki bir evde her öğünde sofraya konan, kırmızı biberle tatlandırılmış ve haftalarca mayalanmış ekşimsi lahana yemeği hangisidir?', 'Kimchi', ['Bulgogi', 'Bibimbap', 'Tteok'], 'Kimchi, fermente sebze yemeğidir; en yaygın türü napa lahanasıyla yapılır ve hemen her Kore sofrasında bulunur.'),
  ('Seul\'de eylül sonunda otoyollar memleketlerine giden ailelerle doluyor; evlerde yarım ay biçimli pirinç kekleri hazırlanıyor ve atalar anılıyor. Hangi bayram kutlanmaktadır?', 'Chuseok', ['Seollal', 'Dano', 'Daeboreum'], 'Chuseok, ay takviminin sekizinci ayının 15. günü kutlanan Kore hasat bayramıdır.'),
  ('Kore\'nin geleneksel kıyafeti olan, kadınlarda kısa bir ceket ve yüksek belli geniş etekten oluşan giysinin adı nedir?', 'Hanbok', ['Kimono', 'Ao dai', 'Qipao'], 'Hanbok, Kore\'ye özgü geleneksel giysidir; kadın hanbokunda jeogori (ceket) ve chima (etek) bulunur.'),
  ('Seul\'de bir lokantada önünüze pirinç, renkli sebzeler, kızarmış yumurta ve kırmızı biber ezmesi dizilmiş bir taş kâse geliyor; garson hepsini karıştırmanızı söylüyor. Bu yemek hangisidir?', 'Bibimbap', ['Japchae', 'Tteokbokki', 'Samgyeopsal'], 'Bibimbap "karıştırılmış pirinç" anlamına gelir; malzemeler yenmeden önce kâsede karıştırılır.'),
  ('Ekim-kasım döneminde Jaipur\'u ziyaret eden bir turist, evlerin pencerelerinin sıra sıra kil kandillerle aydınlatıldığını ve gece boyunca havai fişek atıldığını görüyor. Turist hangi bayrama tanık olmaktadır?', 'Diwali', ['Holi', 'Pongal', 'Onam'], 'Diwali (Deepavali) kandiller ve havai fişeklerle kutlanır; sonbaharda, Kartik ayında yer alır.'),
  ('Mart ayında Hindistan\'da sokağa çıkan bir gezginin beyaz tişörtü birkaç dakika içinde pembe, yeşil ve sarı tozlarla kaplanıyor. Gezgin hangi bayrama denk gelmiştir?', 'Holi', ['Diwali', 'Navratri', 'Raksha Bandhan'], 'Holi "renk bayramı" olarak bilinir; insanlar gulal denen renkli tozları ve renkli suyu birbirine atar.'),
  ('Delhi\'de bir lokantanın mutfağında aşçı hamuru elleriyle yassılaştırıyor ve yuvarlak kil fırının sıcak iç duvarına yapıştırıyor. Hazırlanan ekmek hangisidir?', 'Naan', ['Pide', 'Tortilla', 'Baget'], 'Naan, tandırın sıcak iç yüzeyine yapıştırılarak pişirilen mayalı yassı bir ekmektir.'),
  ('Hint mutfağında kırmızı mercimek gibi kurubaklagillerden yapılan, sofranın temel öğelerinden olan yemeğin genel adı nedir?', 'Dal', ['Raita', 'Paneer', 'Korma'], 'Dal hem kabuğu ayrılmış baklagillerin hem de onlarla yapılan çorbamsı yemeğin adıdır.'),
  ('Hint mutfağında tereyağının ısıtılıp süt katılarının ayrılmasıyla elde edilen ve uzun süre bozulmadan saklanabilen yağın adı nedir?', 'Ghee', ['Paneer', 'Lassi', 'Kheer'], 'Ghee sadeyağa benzer arıtılmış tereyağıdır; hem yemeklerde hem de dinî ritüellerde kullanılır.'),
  ('Hyderabad\'da bir düğün ziyafetinde, safranla renklenmiş uzun taneli pirinç ve baharatlı kuzu etinin kat kat dizilip kapağı hamurla kapatılarak pişirildiği bir yemek sunuluyor. Bu yemek hangisidir?', 'Biryani', ['Pulao', 'Khichdi', 'Pongal'], 'Biryani, baharatlı et ve yarı pişmiş pirincin katmanlar hâlinde dem altında pişirilmesiyle yapılır.'),
  ('Tayland\'da nisan ayında kutlanan yeni yıl bayramı Songkran, en çok hangi uygulamayla tanınır?', 'İnsanların birbirine su sıçratması', ['Gökyüzüne rengârenk uçurtmaların uçurulması', 'Sokaklara renkli toz atılması', 'Gece boyunca oruç tutulması'], 'Songkran\'da su arınmayı simgeler; zamanla dev su savaşlarına dönüşmüştür.'),
  ('Ocak sonu ya da şubatta Hanoi\'de evler şeftali dallarıyla süsleniyor, aileler kare pirinç pastaları hazırlıyor ve atalara tütsü yakıyor. Vietnam\'ın bu ay takvimi yeni yılının adı nedir?', 'Tết', ['Songkran', 'Nyepi', 'Thingyan'], 'Tết Nguyên Đán, Vietnam\'ın en önemli bayramıdır; ailede birleşme ve ataları anma içerir.'),
  ('Kasım dolunayında Chiang Mai\'de insanlar muz yaprağından yapılmış, çiçek ve mumlarla süslü küçük sepetleri dilek tutarak nehre bırakıyor. Hangi bayram kutlanmaktadır?', 'Loy Krathong', ['Songkran', 'Visakha Bucha', 'Makha Bucha'], 'Loy Krathong\'da krathong adlı sepetler suya bırakılarak su tanrıçasına şükran sunulur ve kötülükler uğurlanır.'),
  ('Hanoi\'de sabah kahvaltısında sokak tezgâhından alınan bir kâsede berrak et suyu, yassı pirinç eriştesi ve ince sığır eti dilimleri, yanında da taze otlar bulunuyor. Bu yemek hangisidir?', 'Phở', ['Laksa', 'Tom yum', 'Ramen'], 'Phở kuzey Vietnam kökenli bir erişte çorbasıdır; taze otlar ve misket limonuyla servis edilir.'),
  ('Bangkok\'ta bir seyyar satıcı, kızgın tavada pirinç eriştesini karides, yumurta, tamarind sosu ve fasulye filizleriyle sotelemekte, üzerine dövülmüş fıstık serpmektedir. Satıcının hazırladığı yemek hangisidir?', 'Pad thai', ['Som tam', 'Massaman', 'Khao soi'], 'Pad thai, Tayland\'ın ulusal yemeği olarak tanınan sotelenmiş erişte yemeğidir.'),
  ('Özbekistan\'ın ulusal yemeği sayılan ve kazanda pirinç, havuç, soğan ve etle pişirilen yemek hangisidir?', 'Plov', ['Lagman', 'Manti', 'Samsa'], 'Özbek plovu sarı havuçla pişirilen bir pilavdır; 2016\'da UNESCO somut olmayan miras listesine alınmıştır.'),
  ('Riyad\'da bir eve konuk olan kişiye önce hurma, ardından açık renkli, kakule kokulu bir içecek küçük kulpsuz fincanlarda ikram ediliyor. Konuğa sunulan içecek hangisidir?', 'Gahwa', ['Espresso', 'Kahve-i sade', 'Café au lait'], 'Arap kahvesi (gahwa) açık kavrulmuş çekirdekten, kakuleyle demlenir; genellikle hurmayla birlikte ikram edilir.'),
  ('Bir Bedevi çadırında misafir edilen bir kişi Arap kahvesinden yeterince içtiğini belirtmek istiyor. Gelenekte bunun için ne yapılır?', 'Fincan sağdan sola hafifçe sallanır', ['Fincan ters çevrilip masaya konur', 'Fincana bir hurma çekirdeği bırakılır', 'Ev sahibine yüksek sesle teşekkür edilir'], 'Arap kahvesi geleneğinde fincan hafifçe sallanarak geri verilirse "yeter" anlamına gelir; sallanmazsa fincan yeniden doldurulur.'),
  ('Aralık ayında bir Yahudi ailenin penceresinde sekiz gün boyunca her akşam bir mum daha yakılan dokuz kollu bir şamdan görülüyor. Aile hangi bayramı kutlamaktadır?', 'Hanuka', ['Pesah', 'Purim', 'Sukot'], 'Hanuka, Kudüs\'teki Tapınağın yeniden adanmasını anar; dokuz kollu hanukiya şamdanında her gece bir mum eklenir.'),
  ('Yahudi yeni yılı olan Roş Aşana\'da tatlı bir yıl dileğiyle elma hangi yiyeceğe batırılarak yenir?', 'Bal', ['Zeytinyağı', 'Tuz', 'Yoğurt'], 'Roş Aşana\'da elma bala batırılarak yenir; şofar denen koç boynuzu da çalınır.'),
  ('İsrail\'de sonbaharda bir gün sokaklar boşalıyor, araçlar trafiğe çıkmıyor ve dindar halk yaklaşık bir gün boyunca hiçbir şey yiyip içmeden sinagogda dua ediyor. Bu gün hangisidir?', 'Yom Kipur', ['Şavuot', 'Simhat Tora', 'Tu BiŞvat'], 'Yom Kipur (Kefaret Günü) oruç, dua ve tövbe günüdür.'),
  ('Aralık başında Alman bir çocuk, her sabah karton bir takvimin bir penceresini açıp içinden çıkan çikolatayı yiyor; evdeki çelenkte her pazar bir mum daha yakılıyor. Bu dönemin adı nedir?', 'Advent', ['Lent', 'Epifani', 'Pentekost'], 'Advent "geliş" anlamına gelir; Advent takvimi ve her pazar bir mum yakılan Advent çelengi bu döneme aittir.'),
  ('Birçok Katolik ülkede Paskalya\'dan önceki kırk günlük perhiz dönemi (Lent) başlamadan hemen önce karnavallar düzenlenir. Karnavalın bu zamanlamasının nedeni nedir?', 'Perhizden önce eğlenip bol yemek yeme fırsatı olması', ['Hasadın tam o dönemde bitmesi', 'Yeni yılın tam o hafta başlaması ve kutlanması', 'Kışın en soğuk günlerinin kutlanması'], 'Karnaval, et ve zengin yiyeceklerden uzak durulacak perhiz öncesi son eğlence dönemidir; adının "eti bırakmak" anlamına geldiği düşünülür.'),
  ('Paskalya perhizinin başlamasından önceki salı gününe Fransızca "Yağlı Salı" anlamında verilen ve New Orleans karnavalıyla da özdeşleşen ad nedir?', 'Mardi Gras', ['Ash Wednesday', 'Pancake Day', 'Corpus Christi'], 'Mardi Gras "yağlı salı" demektir; ertesi gün Kül Çarşambası ile perhiz başlar.'),
  ('Birçok ülkede 6 Ocak\'ta kutlanan ve İncil\'e göre doğudan gelen müneccimlerin bebek İsa\'yı ziyaretini anan bayram hangisidir?', 'Epifani', ['Advent', 'Pentekost', 'Kül Çarşambası'], 'Epifani (Teofani) 6 Ocak\'ta kutlanır; İspanya\'da çocuklar hediyelerini bu gün "Üç Kral"dan alır.'),
  ('İngiltere ve birçok Commonwealth ülkesinde Noel\'in ertesi günü olan 26 Aralık\'ın adı nedir?', 'Boxing Day', ['Twelfth Night', 'Guy Fawkes Day', 'St Stephen\'s Night'], 'Boxing Day 26 Aralık\'tır; adının hizmetlilere ve yoksullara verilen hediye kutularından geldiği düşünülür.'),
  ('Noel ağacı süsleme geleneğinin yaygınlaştığı ve 19. yüzyılda İngiltere\'ye Kraliçe Victoria\'nın Alman eşi Prens Albert aracılığıyla da tanıtıldığı ülke hangisidir?', 'Almanya', ['İtalya', 'İsveç', 'Rusya'], 'Süslü Noel ağacı geleneği Almanya\'da gelişmiş, 1840\'larda İngiliz kraliyet ailesiyle popülerlik kazanmıştır.'),
  ('Paskalya yumurtası boyama geleneği birçok kültürde yaygındır. Yumurtanın Paskalya ile ilişkilendirilmesinin simgesel nedeni nedir?', 'Yeni yaşamı ve dirilişi simgelemesi', ['Kışın tek besin olması', 'Tapınaklarda kurban olarak sunulması', 'Sadece yaşlılara ikram edilmesi'], 'Yumurta içinden yeni bir canlı çıktığı için diriliş ve yeniden doğuşun simgesi kabul edilir.'),
  ('Addis Ababa\'da bir lokantada büyük bir tepsinin tabanına serilmiş ekşimsi, süngerimsi bir yassı ekmeğin üzerine yahniler konuyor ve ekmekten koparılan parçalarla yemek alınıyor. Bu ekmek hangisidir?', 'Injera', ['Ugali', 'Fufu', 'Chapati'], 'Injera fermente teff hamurundan yapılır; yemekler doğrudan injeranın üzerine konur ve parçalanan injerayla alınarak yenir.'),
  ('Batı ve Orta Afrika\'da manyok, yam ya da plantain gibi nişastalı besinlerin haşlanıp dövülmesiyle yapılan, çorbalarla birlikte elle yenen hamur kıvamlı yiyecek hangisidir?', 'Fufu', ['Injera', 'Couscous', 'Tagine'], 'Fufu dövülerek hamur kıvamına getirilir; küçük parçalar koparılıp çorbaya batırılarak yenir.'),
  ('Kenya\'da bir safariye katılan gezgin, kırmızı kumaşlara sarınmış, boncuklu takılar takmış, sığır sürüleri güden ve havaya yüksek zıplayarak dans eden bir toplulukla karşılaşıyor. Bu topluluk hangisidir?', 'Maasailer', ['Zulular', 'Yorubalar', 'Tuaregler'], 'Maasailer Kenya ve kuzey Tanzanya\'da yaşayan, sığır yetiştiriciliğine dayalı bir halktır; adumu denen zıplama dansıyla bilinirler.'),
  ('Marakeş çarşısında bir gezgin, konik kapaklı toprak kaplarda saatlerce ağır ateşte pişen kuzu eti ve kuru erikli yahnilerin satıldığını görüyor. Bu kap ve yemeğin ortak adı nedir?', 'Tajin', ['Wok', 'Güveç kazanı', 'Tandır'], 'Tajin hem konik kapaklı kabın hem de içinde pişen yahninin adıdır; kapak buharı yoğunlaştırıp yemeğe geri damlatır.'),
  ('Cezayir, Fas, Moritanya ve Tunus\'un ortak başvurusuyla 2020\'de UNESCO listesine alınan, irmikten küçük taneler hâlinde hazırlanan Mağrip yiyeceği hangisidir?', 'Kuskus', ['Bulgur', 'Firik', 'Arpa şehriye'], 'Kuskus irmiğin elle ovularak küçük tanelere dönüştürülüp buharda pişirilmesiyle yapılır; dört ülkenin ortak dosyasıyla kaydedilmiştir.'),
  ('Tunus mutfağıyla özdeşleşen, kırmızı acı biber, sarımsak ve baharatlardan yapılan ezme hangisidir?', 'Harissa', ['Tahin', 'Chermoula', 'Zahter'], 'Harissa acı biber ezmesidir ve 2022\'de Tunus adına UNESCO somut olmayan miras listesine alınmıştır.'),
  ('Kasım başında Oaxaca\'ya giden bir gezgin, evlerde fotoğraflar, mumlar ve sevilen yiyeceklerle süslü sunaklar kurulduğunu ve mezarlıklarda aileler gece boyu bekleyip şarkı söylediğini görüyor. Gezgin hangi bayrama denk gelmiştir?', 'Ölüler Günü', ['Cinco de Mayo', 'Las Posadas', 'Bağımsızlık Günü'], 'Día de los Muertos\'ta ölen yakınların ruhlarının ziyarete geldiğine inanılır; kutlama hüzünden çok sevgi ve neşe taşır.'),
  ('Meksika\'daki Ölüler Günü sunaklarına (ofrenda) konan ve parlak turuncu rengiyle ruhlara yol gösterdiğine inanılan çiçek hangisidir?', 'Kadife çiçeği', ['Kırmızı gül', 'Beyaz zambak', 'Ayçiçeği'], 'Cempasúchil (kadife çiçeği) güçlü kokusu ve rengiyle ruhları sunağa çektiği düşünülen çiçektir.'),
  ('Bir Meksika lokantasında mısır cipsinin yanında, ezilmiş avokado, misket limonu, soğan ve kişnişten hazırlanmış yeşil bir sos getiriliyor. Bu sos hangisidir?', 'Guacamole', ['Mole poblano', 'Salsa roja', 'Chimichurri'], 'Guacamole adı Nahuatl dilinde "avokado sosu" anlamındaki ahuacamolli sözcüğünden gelir.'),
  ('Meksika\'da mısır hamurunun mısır kabuğuna sarılıp buharda pişirilmesiyle yapılan tamales özellikle bayramlarda çok sayıda hazırlanır. Tamalesin tarihsel olarak yaygınlaşmasında hangi özelliği etkili olmuştur?', 'Taşınabilir ve dayanıklı bir yiyecek olması', ['Yalnızca saray şeflerince hazırlanabilmesi', 'İçinde mutlaka çikolata bulunması', 'Çiğ olarak tüketilmesi'], 'Tamales sarılı yapısı sayesinde kolay taşınır ve saklanır; bu yüzden yolculuklarda ve savaşlarda bile kullanılmıştır.'),
  ('Lima\'da bir lokantada çiğ deniz levreği küp küp doğranıp misket limonu suyu, kırmızı soğan ve acı biberle birkaç dakika bekletildikten sonra servis ediliyor. Bu yemek hangisidir?', 'Ceviche', ['Lomo saltado', 'Anticucho', 'Ají de gallina'], 'Ceviche\'de limon suyunun asidi balık proteinlerini denatüre ederek pişmiş gibi bir doku verir.'),
  ('Arjantin ve Uruguay\'da etin açık ateşte ya da ızgarada uzun süre pişirildiği toplumsal yemek geleneğinin adı nedir?', 'Asado', ['Churrasco rodízio', 'Feijoada', 'Locro'], 'Asado, Arjantin ve Uruguay\'da ailelerin ve arkadaşların bir araya geldiği temel et pişirme geleneğidir.'),
  ('Brezilya\'nın ulusal yemeği sayılan, siyah fasulyenin farklı domuz ve sığır etleriyle pişirildiği yahni hangisidir?', 'Feijoada', ['Moqueca', 'Coxinha', 'Vatapá'], 'Feijoada siyah fasulye ve etle yapılır; genellikle pirinç, farofa ve portakalla servis edilir.'),
  ('Kasım sonunda ABD\'de yaşayan bir aile perşembe günü bir araya gelip fırında bütün bir hindi, kızılcık sosu ve balkabağı turtası hazırlıyor. Aile hangi bayramı kutlamaktadır?', 'Şükran Günü', ['Bağımsızlık Günü', 'İşçi Bayramı', 'Anma Günü'], 'Thanksgiving ABD\'de kasımın dördüncü perşembesi kutlanır; geleneksel sofrada hindi, kızılcık sosu ve balkabağı turtası bulunur.'),
  ('ABD\'de 2 Şubat\'ta bir dağ sıçanının yuvasından çıkıp gölgesini görüp görmemesine göre kışın uzayıp uzamayacağının "tahmin edildiği" gelenek hangisidir?', 'Groundhog Day', ['Arbor Day', 'Labor Day', 'Flag Day'], 'Groundhog Day en çok Pennsylvania\'daki Punxsutawney kasabasıyla özdeşleşmiştir.'),
  ('ABD\'de 31 Ekim akşamı kostüm giymiş çocuklar kapı kapı dolaşıp "Trick or treat!" diyerek şeker istiyor. Bu hangi gelenektir?', 'Cadılar Bayramı', ['Şükran Günü', 'Sevgililer Günü', 'Aziz Patrick Günü'], 'Halloween, kökenleri Kelt Samhain bayramına uzanan ve kostüm, balkabağı feneri ve şeker toplamayla bilinen bir gelenektir.'),
  ('31 Ekim akşamı ABD\'de bir sokakta evlerin önüne içi oyulmuş, gülümseyen yüz biçiminde delikler açılmış ve içine mum konmuş turuncu kabaklar diziliyor. Bu süslerin adı nedir?', 'Jack-o\'-lantern', ['Will-o\'-wisp', 'Candy corn', 'Scarecrow'], 'Jack-o\'-lantern geleneği İrlanda\'da şalgamla yapılırdı; Amerika\'da daha kolay oyulan balkabağına geçildi.'),
  ('Kanada\'nın Québec eyaletinden doğan, kızarmış patatesin peynir parçaları ve et sosuyla servis edildiği yemek hangisidir?', 'Poutine', ['Tourtière', 'Bannock', 'Butter tart'], 'Poutine 1950\'lerde kırsal Québec\'te ortaya çıkmış ve Kanada\'nın simge yemeklerinden biri olmuştur.'),
  ('Kanada bayrağında da yer alan akçaağaç, ülkenin mutfak kültüründe neden önemlidir?', 'Özsuyundan akçaağaç şurubu üretilmesi', ['Yapraklarının salata ve çorbalarda kullanılması', 'Kökünden un yapılması', 'Kabuğundan çay demlenmesi'], 'Kanada dünyadaki akçaağaç şurubunun büyük bölümünü üretir; şurup ilkbaharda ağaçların özsuyunun kaynatılmasıyla elde edilir.'),
  ('Edinburgh\'da 25 Ocak gecesi verilen bir ziyafette gayda eşliğinde salona getirilen, koyun sakatatı ve yulafla yapılan yemeğe bir şiir okunuyor. Bu yemek hangisidir?', 'Haggis', ['Shepherd\'s pie', 'Black pudding', 'Cornish pasty'], 'Burns Supper\'da haggis gaydayla salona getirilir ve Burns\'ün "Address to a Haggis" şiiri okunur.'),
  ('Mart ortasında Dublin sokakları yeşil giysili kalabalıklarla doluyor, geçit törenleri yapılıyor ve insanlar yakalarına üç yapraklı yonca takıyor. Hangi gün kutlanmaktadır?', 'Aziz Patrick Günü', ['Aziz Andrew Günü', 'Aziz David Günü', 'Aziz George Günü'], 'Saint Patrick\'s Day, İrlanda\'ya Hristiyanlığı yaydığı kabul edilen Aziz Patrick\'i anar; üç yapraklı yonca (shamrock) simgedir.'),
  ('İskoçya\'da yılbaşı kutlamalarına verilen ad nedir?', 'Hogmanay', ['Ceilidh', 'Beltane', 'Samhain'], 'Hogmanay İskoçya\'nın yılbaşıdır; gece yarısı "Auld Lang Syne" söylenir.'),
  ('Brighton sahilinde bir büfe, gazete kâğıdına sarılı, hamura bulanıp kızartılmış morina parçalarını kalın patates kızartmasıyla birlikte satıyor. Bu yemeğin adı nedir?', 'Fish and chips', ['Bangers and mash', 'Toad in the hole', 'Ploughman\'s lunch'], 'Fish and chips 19. yüzyılın ortalarından beri İngiltere\'nin simge sokak yemeklerindendir.'),
  ('İrlanda\'nın geleneksel yahnisi olan "Irish stew" esas olarak hangi etle yapılır?', 'Kuzu ya da koyun eti', ['Domuz pastırması', 'Tavuk', 'Ringa balığı'], 'Klasik Irish stew koyun ya da kuzu eti, patates, soğan ve havuçla yapılır.'),
  ('Paris\'te yaşayan aile 14 Temmuz\'da Champs-Élysées\'deki askerî geçit törenini izliyor. Bu ulusal bayram hangi olayın yıldönümüdür?', 'Bastille Hapishanesi\'nin basılması', ['Napolyon\'un taç giymesi', 'Paris Barışı\'nın imzalanması', 'Fransa\'nın Kurtuluşu'], '14 Temmuz 1789\'da Bastille\'in alınması Fransız Devrimi\'nin simgesi olmuştur.'),
  ('Fransa\'da Epifani döneminde içine küçük bir figürin (fève) saklanan ve figürini bulanın o günün "kralı" olduğu pasta hangisidir?', 'Galette des rois', ['Bûche de Noël', 'Tarte Tatin', 'Paris-Brest'], 'Galette des rois genellikle badem kremalı milföyden yapılır; figürini bulan kişi kâğıt tacı takar.'),
  ('Fransa\'da Noel\'de yenen, kütük biçiminde hazırlanan rulo pastanın adı nedir?', 'Bûche de Noël', ['Galette des rois', 'Mille-feuille', 'Croquembouche'], 'Bûche de Noël, eski Noel kütüğü yakma geleneğinden esinlenen kütük biçimli bir pastadır.'),
  ('Bir aşçılık öğrencisi tavada un ve tereyağını kavurup azar azar sıcak süt ekleyerek koyu, beyaz bir sos hazırlıyor ve muskat rendeliyor. Öğrencinin hazırladığı ana sos hangisidir?', 'Beşamel', ['Hollandez', 'Velouté', 'Espagnole'], 'Beşamel roux denen un-tereyağı karışımına süt eklenerek yapılır; velouté ise süt yerine açık renkli et suyuyla yapılır.'),
  ('Rivayete göre 1889\'da Kraliçe Margherita onuruna İtalyan bayrağının renklerini taşıyacak biçimde hazırlanan pizzanın malzemeleri hangileridir?', 'Domates, mozzarella ve fesleğen', ['Salam, mantar ve zeytin', 'Ançüez, kapari ve kekik', 'Patates, biberiye ve parmesan peyniri'], 'Pizza Margherita\'da kırmızı domates, beyaz mozzarella ve yeşil fesleğen bayrağın üç rengini temsil eder.'),
  ('İtalya\'da makarnanın "al dente" pişirilmesi istenir. Bu ifade makarnanın hangi kıvamda olduğunu anlatır?', 'Dişe hafifçe direnç gösterecek kadar pişmiş', ['İyice yumuşayıp neredeyse dağılacak kadar uzun pişmiş', 'Hiç haşlanmadan fırınlanmış', 'Kızartılıp çıtır hâle getirilmiş'], 'Al dente "dişe" demektir; makarna tamamen yumuşamadan, ortasında hafif bir sertlik kalacak şekilde haşlanır.'),
  ('Milano\'da bir aşçı, kısa ve nişastalı pirinci tereyağında çevirdikten sonra üzerine azar azar sıcak et suyu ekleyip sürekli karıştırıyor; sonunda safran ve parmesan ekliyor. Hazırlanan yemek hangisidir?', 'Risotto', ['Polenta', 'Gnocchi', 'Minestrone'], 'Risotto Arborio ya da Carnaroli gibi nişastalı pirinçlerle yapılır; Milano usulü safranla renklendirilir.'),
  ('Aralıkta Milano\'daki bir pastanede uzun süre mayalanmış, kuru üzüm ve şekerlenmiş portakal kabuğu içeren, kubbe biçimli yüksek tatlı ekmekler kutulara konup satılıyor. Bu ekmek hangisidir?', 'Panettone', ['Pandoro', 'Cannoli', 'Panna cotta'], 'Panettone uzun mayalanan, kuru üzüm ve şekerlenmiş kabuklu meyve içeren bir Milano çöreğidir; Pandoro ise Verona\'nın yıldız biçimli sade çöreğidir.'),
  ('Ağustosun son çarşambası Buñol\'a giden bir gezgin, kamyonlardan dökülen tonlarca olgun kırmızı sebzenin kalabalıkça birbirine fırlatıldığını görüyor. Bu festival hangisidir?', 'La Tomatina', ['San Fermín', 'Las Fallas', 'Semana Santa'], 'La Tomatina ağustosun son çarşambası yapılır; onlarca ton olgun domates eğlence için kullanılır.'),
  ('Temmuz başında Pamplona\'da beyaz giysili ve kırmızı fularlı kalabalık, dar sokaklarda arkalarından koşan boğaların önünde arenaya doğru koşuyor. Bu festival hangisidir?', 'San Fermín', ['La Tomatina', 'Feria de Abril', 'La Mercè'], 'San Fermín, Ernest Hemingway\'in "Güneş de Doğar" romanıyla dünyaca tanınmıştır.'),
  ('Madrid\'de yılbaşı gecesi Puerta del Sol\'daki saat gece yarısını vururken insanlar her çan sesiyle birlikte bir şey yiyor. Bu geleneğe göre ne ve kaç tane yenir?', 'On iki üzüm', ['On iki zeytin', 'Yedi badem', 'Dokuz incir'], '"Las doce uvas" geleneğinde her çana bir üzüm yenir; bunun yeni yılın her ayına şans getirdiğine inanılır.'),
  ('Valencia\'da bir pazar öğleni aile, açık havada geniş ve sığ bir tavada safranlı pirinci tavşan, tavuk ve fasulyeyle pişiriyor. Hazırlanan yemek hangisidir?', 'Paella', ['Gazpacho', 'Tortilla española', 'Fabada asturiana'], 'Paella adını pişirildiği tavadan alır; özgün Valencia paellası tavşan, tavuk ve fasulyeyle yapılır.'),
  ('Sevilla\'da bunaltıcı bir temmuz öğleninde garson, domates, salatalık, biber, sarımsak ve zeytinyağıyla hazırlanmış buz gibi bir çorba getiriyor. Bu çorba hangisidir?', 'Gazpacho', ['Paella', 'Cocido madrileño', 'Pisto manchego'], 'Gazpacho sıcak Endülüs yazında serinletici olarak tüketilen soğuk bir sebze çorbasıdır.'),
  ('Lizbon\'daki Belém semtiyle özdeşleşen, çıtır hamur içinde yumurtalı krema bulunan Portekiz tatlısı hangisidir?', 'Pastel de nata', ['Bolo rei', 'Pão de ló', 'Arroz doce'], 'Pastel de nata, 19. yüzyılda Jerónimos Manastırı\'ndaki rahiplerin tarifine dayandırılır.'),
  ('Lizbon ve Coimbra ile özdeşleşen, hasret ve hüzün dolu şarkılarıyla tanınan ve UNESCO listesinde yer alan Portekiz müzik türü hangisidir?', 'Fado', ['Flamenko', 'Morna', 'Tango'], 'Fado\'nun temel duygusu "saudade" (özlem, hasret) kavramıyla anlatılır.'),
  ('Eylül sonunda Münih\'e giden bir gezgin, Theresienwiese\'de dev çadırlar, dirndl ve lederhosen giymiş kalabalıklar ve bando müziğiyle karşılaşıyor. Gezgin hangi festivale denk gelmiştir?', 'Oktoberfest', ['Karneval', 'Fasching', 'Walpurgisnacht'], 'Oktoberfest ilk kez 1810\'da Veliaht Prens Ludwig\'in düğünü vesilesiyle düzenlenmiştir.'),
  ('Viyana\'da bir lokantada çok ince dövülmüş dana etinin ekmek kırıntısına bulanıp tereyağında kızartılmış hâli, limon dilimiyle birlikte servis ediliyor. Bu yemek hangisidir?', 'Wiener Schnitzel', ['Tafelspitz', 'Sauerbraten', 'Bratwurst'], 'Wiener Schnitzel (Viyana usulü şnitzel) geleneksel olarak dana etinden yapılır ve limonla sunulur.'),
  ('Zermatt\'ta bir dağ evinde arkadaşlar, ortadaki küçük ocağın üzerindeki kapta eriyen peynire uzun çatallarla ekmek küpleri batırıyor. Bu yemek hangisidir?', 'Fondü', ['Raclette', 'Rösti', 'Birchermüesli'], 'Fondü genellikle Gruyère ve Vacherin gibi peynirlerle yapılır; raclette ise eritilen peynirin kazınarak patatesle yenmesidir.'),
  ('İsveç\'te haziran sonunda çiçeklerle süslü bir direğin çevresinde dans edilerek kutlanan ve yılın en uzun günleriyle ilişkili bayram hangisidir?', 'Midsommar', ['Lucia', 'Jul', 'Påsk'], 'Midsommar, yaz gündönümüne yakın bir cuma kutlanır; ringa balığı, yeni patates ve çilek geleneksel yiyeceklerdir.'),
  ('İsveç\'te "fika" kelimesi gündelik hayatta sık kullanılır. Bir İsveçli iş arkadaşı sizi fikaya çağırırsa ne yapmayı öneriyordur?', 'Kahve ve tatlı eşliğinde kısa bir sohbet molası vermeyi', ['Akşam bir sauna seansına katılmayı', 'Hafta sonu ormanda yürüyüş yapmayı', 'Ortak bir öğle yemeği hazırlamayı ve bulaşığı paylaşmayı'], 'Fika, genellikle kahve ve tarçınlı çörek gibi bir tatlıyla yapılan, toplumsal bağı güçlendiren mola geleneğidir.'),
  ('Fin kültürünün ayrılmaz parçası olan ve 2020\'de UNESCO listesine alınan gelenek hangisidir?', 'Sauna kültürü', ['Ren geyiği güdücülüğü', 'Buz balıkçılığı', 'Kantele yapımı'], 'Finlandiya\'da milyonlarca sauna bulunur; sauna, arınma ve sosyalleşme yeri olarak kabul edilir.'),
  ('Norveç\'te kurutulmuş morinanın kül suyunda bekletilip jöle kıvamına getirilmesiyle hazırlanan ve Noel\'de yenen geleneksel yemek hangisidir?', 'Lutefisk', ['Rakfisk', 'Gravlaks', 'Surströmming'], 'Lutefisk kül suyu (lye) ile işlenmiş kuru balıktır; Norveç ve İsveç\'te Noel sofrasında yer alır.'),
  ('Moskova\'da bir hediyelik eşya dükkânında açtıkça içinden giderek küçülen bir başka ahşap bebeğin çıktığı boyalı oyuncaklar satılıyor. Bu oyuncakların adı nedir?', 'Matruşka', ['Balalayka', 'Samovar', 'Kokoşnik'], 'Matruşka bebekleri 1890\'larda Rusya\'da yapılmaya başlanmıştır.'),
  ('Rusya\'da Paskalya perhizinden önceki hafta kutlanan ve bol bol blini (ince krep) yenen bayramın adı nedir?', 'Maslenitsa', ['Ivan Kupala', 'Svyatki', 'Radonitsa'], 'Maslenitsa "tereyağı haftası"dır; yuvarlak blini güneşi simgeler ve sonunda kışı temsil eden bir saman kukla yakılır.'),
  ('Kiev\'de bir lokantada pancar, lahana ve etle yapılmış koyu kırmızı renkli bir çorba, üzerine bir kaşık ekşi krema konarak servis ediliyor. Bu çorba hangisidir?', 'Borş', ['Şçi', 'Solyanka', 'Okroşka'], 'Borş\'un rengi pancardan gelir; Ukrayna borş pişirme kültürü 2022\'de UNESCO acil koruma listesine alınmıştır.'),
  ('Polonya mutfağında patates, peynir, et ya da lahana ile doldurulan hamur cepleri olan ve mantıya benzeyen yiyeceğin adı nedir?', 'Pierogi', ['Gołąbki', 'Bigos', 'Kiełbasa'], 'Pierogi haşlanır ya da tavada kızartılır; Noel arifesi sofrasında da önemli yer tutar.'),
  ('Rusya\'da misafirleri karşılarken bir tepside ekmek ve tuz sunulur. Bu karşılama geleneğinin anlamı nedir?', 'Konukseverlik ve konuğa saygı', ['Konuğun yemek yemeden gitmesi dileği', 'Yeni bir yılın başladığının duyurulması', 'Konuktan karşılık beklendiğinin bildirilmesi'], '"Hleb-sol" geleneğinde konuk ekmekten bir parça koparıp tuza batırır; bu, hoş geldin ve ev sahibine güvenin ifadesidir.'),
  ('Atina\'da bir tavernada patlıcan dilimleri, kıymalı domates sosu ve kalın bir beşamel tabakasından oluşan fırınlanmış bir yemek sunuluyor. Bu yemek hangisidir?', 'Musakka', ['Pastitsio', 'Spanakopita', 'Gyros'], 'Yunan musakkası beşamel tabakasıyla karakterize edilir; pastitsio ise makarnayla yapılan benzer bir fırın yemeğidir.'),
  ('5 Aralık akşamı Amsterdam\'da bir çocuk, ayakkabısına bıraktığı havucun yerinde hediyeler buluyor; çocuk bunları kırmızı cübbeli, beyaz sakallı bir azizin getirdiğine inanıyor. Hangi bayram kutlanmaktadır?', 'Sinterklaas', ['Koningsdag', 'Carnaval', 'Bevrijdingsdag'], 'Sinterklaas (Aziz Nikolaos) Hollanda\'da Noel Baba figürünün kökenlerinden biri sayılır; hediyeler 5 Aralık akşamı verilir.'),
  ('Belçika\'da ulusal bir yiyecek sayılan, kâğıt külahlarda genellikle mayonezle satılan ve iki kez kızartılan yiyecek hangisidir?', 'Patates kızartması', ['Brüksel lahanası', 'Belçika waffle\'ı', 'Midye buğulama'], 'Belçika\'da "frieten" ya da "frites" denen patates kızartması ulusal bir simgedir; geleneksel olarak iki kez kızartılır.'),
  ('Hollanda\'da iki ince waffle arasına karamel şurubu sürülerek yapılan ve Gouda kentiyle özdeşleşen tatlı hangisidir?', 'Stroopwafel', ['Poffertjes', 'Oliebollen', 'Speculaas'], 'Stroopwafel 18.-19. yüzyılda Gouda\'da ortaya çıkmıştır; sıcak çay ya da kahve fincanının üstüne konup ısıtılarak yenir.'),
  ('Bir ragbi maçı öncesinde Yeni Zelanda takımı rakibin karşısına dizilip ayaklarını yere vurarak, dillerini çıkararak ve ritmik bağırışlarla törensel bir gösteri yapıyor. Bu gösterinin adı nedir?', 'Haka', ['Hula', 'Poi', 'Tamure'], 'Haka savaş öncesi de yapılırdı; günümüzde törenlerde ve Yeni Zelanda ragbi takımının maç öncesinde görülür.'),
  ('Sydney\'de Noel sofrasında kabuğu çıtır, içi yumuşak bir beze tabanın üzerine çırpılmış krema, kivi ve çilek konmuş bir tatlı sunuluyor. Bu tatlı hangisidir?', 'Pavlova', ['Lamington', 'Anzac bisküvisi', 'Tim Tam'], 'Pavlova, 1920\'lerde iki ülkeyi ziyaret eden Rus balerin Anna Pavlova\'nın adını taşır.'),
  ('Avustralya ve Yeni Zelanda\'da her yıl 25 Nisan\'da Çanakkale\'ye çıkarmanın yıldönümünde savaşta hayatını kaybedenlerin anıldığı gün hangisidir?', 'Anzak Günü', ['Avustralya Günü', 'Waitangi Günü', 'Anma Pazarı'], 'Anzac Day 25 Nisan 1915\'te Gelibolu\'ya yapılan çıkarmanın yıldönümüdür; şafak ayinleriyle anılır.'),
  ('Hawaii\'de bir misafire boynuna çiçekten bir çelenk (lei) takılması hangi anlamı taşır?', 'Sevgi, saygı ve hoş geldin dileğini', ['Misafirin hemen ayrılması gerektiğini', 'Bir yarışmanın kaybedildiğini', 'Misafirin aileye borçlandığını'], 'Lei, karşılama, uğurlama ve kutlamalarda sevgi ve saygı ifadesi olarak verilir.'),
  ('Kuzey Amerika yerli halklarının dans, şarkı ve davul eşliğinde bir araya geldiği, günümüzde de yaygın olarak düzenlenen toplanma şenliklerine ne ad verilir?', 'Powwow', ['Potlatch', 'Pueblo', 'Wigwam'], 'Powwow\'larda farklı kabilelerden dansçılar renkli giysilerle yarışır ve kültürel kimlik kutlanır.'),
  ('Avustralya\'nın kuzeyindeki Arnhem Land\'de bir Aborijin müzisyen, içi termitlerce oyulmuş uzun bir okaliptüs gövdesine üfleyerek kesintisiz, derin ve titreşimli bir ses çıkarıyor. Bu çalgı hangisidir?', 'Didgeridoo', ['Bumerang', 'Kantele', 'Sitar'], 'Didgeridoo içi termitlerce oyulmuş okaliptüs gövdesinden yapılır; dairesel solunumla kesintisiz çalınır.'),
  ('Kanada Arktiği\'nde bir İnuit avcı, av sırasında geceyi geçirmek için sıkıştırılmış kar bloklarını spiral biçiminde dizerek kubbe şeklinde bir barınak kuruyor. Bu barınağın adı nedir?', 'İglo', ['Tipi', 'Yurt', 'Hogan'], 'İglo, sıkıştırılmış kar bloklarıyla kurulur; kar iyi bir yalıtkan olduğundan içi dışarıya göre çok daha sıcaktır.'),
  ('Kuzey Amerika\'nın Büyük Ovalar halklarının konik çadırı tipinin, bizon avının yaygın olduğu bu bölgedeki yaşama uygunluğu nereden gelir?', 'Kolay kurulup taşınabilmesi ve bizon derisinden yapılması', ['Taş ve kerpiçten, yıllarca dayanacak kadar sağlam yapılması', 'Yalnızca bayramlarda kurulması', 'Nehir üzerinde yüzebilmesi'], 'Tipi direklerle hızla kurulup sökülebilir; bizon sürülerini izleyen göçebe yaşama uygundur.'),
  ('Bir gezgin yılbaşı gecesi Ekvador\'da sokaklarda yakılan büyük kuklalar görüyor. Bu "año viejo" kuklalarının yakılması neyi simgeler?', 'Eski yılın kötülüklerini geride bırakmayı', ['Bir savaş zaferini kutlamayı', 'Ölmüş bir kralın yasını', 'Hasadın başlamasını'], 'Año viejo (eski yıl) kuklaları gece yarısı yakılarak geçen yılın kötü anıları simgesel olarak yok edilir.'),
  ('Yılbaşı gecesi Londra\'da saat 12\'yi vurduğunda kalabalık kollarını çaprazlayıp el ele tutuşuyor ve Robert Burns\'ün sözlerini yazdığı eski dostlukları anan şarkıyı söylüyor. Bu şarkı hangisidir?', 'Auld Lang Syne', ['Jingle Bells', 'Danny Boy', 'God Save the King'], 'Robert Burns\'ün kaleme aldığı "Auld Lang Syne" eski dostlukları anan bir şarkıdır ve dünyanın birçok yerinde yılbaşında söylenir.'),
  ('İspanyolca konuşan bazı ülkelerde yılbaşı gecesi boş bir bavulla sokakta tur atılır. Bu davranışla dile getirilen dilek nedir?', 'Yeni yılda bol bol seyahat etmek', ['Eski yılın eşyalarından kurtulmak', 'Bir taşınmanın sonuna gelmek', 'Yeni bir işe başlamak'], 'Latin Amerika\'da yaygın olan bu gelenekte boş bavulla dolaşmak yeni yılda yolculuklar yapma dileğini simgeler.'),
  ('Hindistan\'da düğün öncesinde gelinin ellerine ve ayaklarına kına ile ince desenlerin çizildiği törene ne ad verilir?', 'Mehndi', ['Sangeet', 'Haldi', 'Baraat'], 'Mehndi töreninde kına desenleri çizilir; desenin koyuluğunun evlilikteki sevgiye işaret ettiğine dair inanışlar vardır.'),
  ('Şanghay\'da geleneksel bir düğüne katılan bir konuk, gelinin giysisinden davetiyelere ve para zarflarına kadar her şeyin aynı renkte olduğunu fark ediyor. Bu renk hangisidir?', 'Kırmızı', ['Beyaz', 'Mavi', 'Gümüş grisi'], 'Çin kültüründe kırmızı şans ve mutluluğu simgeler; beyaz ise geleneksel olarak yasla ilişkilendirilir.'),
  ('İngiltere\'de bir gelin düğün günü için "something old, something new, something borrowed, something blue" sözüne uygun hazırlanıyor. Buna göre yanında hangisini bulundurması gerekir?', 'Ödünç alınmış bir eşya', ['Yeni doğmuş bir hayvan', 'Kırmızı bir çiçek', 'Ateşte yakılmış bir mektup'], 'Söze göre gelin eski, yeni, ödünç alınmış ve mavi birer şey taşır; bunların uğur getirdiğine inanılır.'),
  ('Chennai\'de bir düğüne katılan kadın konuklar, beş-dokuz metrelik tek parça renkli ipek kumaşı bir bluz üzerine bedenlerine dolayarak giyinmiş. Bu giysi hangisidir?', 'Sari', ['Kimono', 'Kilt', 'Ponço'], 'Sari genellikle bir bluz (choli) ve iç etekle giyilir; dolama biçimi bölgeden bölgeye değişir.'),
  ('Edinburgh\'da bir düğünde damat, ailesinin klanına özgü ekose desenli, dizboyu yün bir eteklik ve önüne asılı deri bir kese takmış. Damadın giydiği bu giysi hangisidir?', 'Kilt', ['Sporran', 'Tartan', 'Bagpipe'], 'Kilt geleneksel olarak yünlü tartandan yapılır; önüne sporran denen deri bir kese asılır.'),
  ('Oktoberfest\'te garsonluk yapan bir kadın, korsajlı bir elbise, kısa kollu beyaz bir bluz ve beline bağlı bir önlük giymiş. Bu geleneksel giysi hangisidir?', 'Dirndl', ['Lederhosen', 'Tracht şapkası', 'Loden ceket'], 'Dirndl kadın giysisidir; erkekler ise lederhosen denen deri pantolon giyer. Önlüğün bağlandığı tarafın medeni hâli gösterdiği söylenir.'),
  ('Vietnam\'da kadınların giydiği, pantolon üzerine giyilen uzun ve yırtmaçlı tunik biçimindeki ulusal giysi hangisidir?', 'Ao dai', ['Hanbok', 'Sampot', 'Kebaya'], 'Ao dai ince ipekten yapılır ve Vietnam\'ın ulusal giysisi olarak kabul edilir.'),
  ('Hindistan\'da sütlü çayın zencefil, kakule, tarçın ve karanfil gibi baharatlarla kaynatılmasıyla hazırlanan içeceğin adı nedir?', 'Masala chai', ['Kahwa', 'Lassi', 'Thandai'], 'Masala chai Hindistan\'ın sokak çaycılarında (chai wallah) yaygın olarak satılır.'),
  ('Güney Afrika\'ya özgü, Camellia sinensis değil bir baklagil çalısından elde edilen ve kafein içermeyen kırmızı çay hangisidir?', 'Rooibos', ['Darjeeling', 'Assam', 'Earl Grey'], 'Rooibos ("kırmızı çalı") Batı Kap bölgesinin Cederberg dağlarında yetişen Aspalathus linearis bitkisinden yapılır.'),
  ('Bergamot portakalının kabuk yağıyla aromalandırılmış, bir İngiliz başbakanının adını taşıyan siyah çay karışımı hangisidir?', 'Earl Grey', ['Lady Grey', 'English Breakfast', 'Darjeeling'], 'Earl Grey, 1830\'larda başbakanlık yapan 2. Earl Grey Charles Grey\'in adını taşır.'),
  ('Malezya\'da "teh tarik" yapılırken sütlü çay iki kap arasında yüksekten defalarca dökülür. Bu işlemin sonucu nedir?', 'Çayın köpürmesi ve içilecek ısıya inmesi', ['Çayın yeniden kaynaması', 'Çayın rengini koyulaştırıp acılaştırması', 'Çayın rengini tamamen kaybetmesi'], '"Teh tarik" "çekilmiş çay" demektir; yüksekten dökme köpük oluşturur, karışımı harmanlar ve çayı biraz soğutur.'),
  ('Bir kahve tarihçisi arabika kahvesinin yabani olarak yetiştiği ilk yaylaları görmek istiyor. Bu araştırma için gitmesi gereken ülke hangisidir?', 'Etiyopya', ['Yemen', 'Brezilya', 'Kolombiya'], 'Arabika kahvesi Etiyopya yaylalarında yabani olarak yetişir; kahvenin içecek olarak yaygınlaşması ise Yemen\'de olmuştur.'),
  ('Roma\'da bir barda barista ince öğütülmüş kahveyi makinenin haznesine sıkıştırıyor ve basınçlı sıcak suyla yirmi-otuz saniyede küçük bir fincan koyu, üstü köpüklü kahve hazırlıyor. Bu kahvenin adı nedir?', 'Espresso', ['Latte', 'Americano', 'Frappé'], 'Espresso, 20. yüzyıl başında İtalya\'da geliştirilen makinelerle yaygınlaştı; pek çok kahve içeceğinin temelidir.'),
  ('Lyon\'da bir fırının önünde sabah sıraya giren insanlar, koltuk altlarına sıkıştırdıkları uzun, ince ve çıtır kabuklu ekmeklerle çıkıyor. Bu ekmeğin adı nedir?', 'Baget', ['Brioche', 'Focaccia', 'Ciabatta'], 'Baget (baguette) Fransız ekmeğinin simgesidir; zanaat ve kültürü 2022\'de UNESCO listesine alınmıştır.'),
  ('Mexico City\'de bir kadın, kireçli suda pişirilmiş mısırdan yaptığı hamuru küçük toplara ayırıp bastırarak inceltiyor ve sacda pişiriyor; bunlar daha sonra taco olarak doldurulacak. Hazırlanan yiyecek hangisidir?', 'Tortilla', ['Arepa', 'Chapati', 'Naan'], 'Tortilla Mezoamerika\'nın binlerce yıllık temel besinidir; taco ve burrito gibi yemeklerin tabanını oluşturur.'),
  ('Ekşi maya (sourdough) ile yapılan ekmeklerin kendine özgü ekşimsi tadı nereden gelir?', 'Hamurdaki yabani maya ve laktik asit bakterilerinin fermantasyonundan', ['Hamura limon suyu eklenmesinden', 'Ekmeğin pişirildikten sonra sirkeyle fırçalanmasından', 'Unun pişmeden önce kızartılmasından'], 'Ekşi maya kültürü yabani mayalar ve laktik asit bakterileri içerir; bunların ürettiği asitler ekşi tat verir.'),
  ('Güney Almanya\'da yaygın olan, düğüm biçiminde bükülmüş, kabuğu sodalı suda haşlanarak parlak kahverengi olan hamur işi hangisidir?', 'Brezel', ['Croissant', 'Bagel', 'Stollen'], 'Brezel kostik soda çözeltisine batırılarak pişirilir; bu, kabuğa koyu rengini ve özgün tadını verir.'),
  ('Hindistan\'da tam buğday unundan mayasız yapılan ve sacda pişirilen ince yassı ekmek hangisidir?', 'Chapati', ['Naan', 'Kulcha', 'Bhatura'], 'Chapati (roti) günlük öğünlerin temel ekmeğidir; naan ise mayalı olup tandırda pişer.'),
  ('New York\'ta bir fırıncı halka biçimli hamurları fırına vermeden önce kısa süre kaynar suda haşlıyor; sabahları bunlar krem peynir ve füme somonla satılıyor. Bu ekmek hangisidir?', 'Bagel', ['Brezel', 'Simit', 'Challah'], 'Bagel önce kısa süre kaynar suda haşlanır sonra fırınlanır; bu yöntem yoğun ve çiğnenebilir bir doku verir.'),
  ('Bir İtalyan şarküterisinde çok büyük bir tekerleğin üzerinde "Emilia-Romagna, inek sütü, en az on iki ay olgunlaştırılmış" yazıyor. Bu sert peynir hangisidir?', 'Parmigiano Reggiano', ['Mozzarella di bufala', 'Gorgonzola', 'Ricotta'], 'Parmigiano Reggiano korumalı menşe adına sahiptir; yalnız belirli bölgelerde, belirli kurallarla üretilebilir.'),
  ('Fransa\'da koyun sütünden yapılan ve Combalou Dağı\'ndaki doğal mağaralarda olgunlaştırılan mavi küflü peynir hangisidir?', 'Roquefort', ['Camembert', 'Brie', 'Comté'], 'Roquefort Penicillium roqueforti küfüyle mavi damarlar kazanır; 1925\'te Fransa\'nın ilk menşe adı koruması alan peyniridir.'),
  ('Yunanistan\'da AB koruma statüsüne sahip olan, koyun sütü ya da koyun-keçi sütü karışımından yapılan ve salamurada saklanan beyaz peynir hangisidir?', 'Feta', ['Halloumi', 'Manchego', 'Pecorino'], 'Feta 2002\'den beri AB\'de Yunanistan\'a özgü korumalı menşe adıdır; en az %70 koyun sütü içermelidir.'),
  ('Hollanda\'da adını verildiği kentin peynir pazarından alan, sarı renkli ve tekerlek biçimli inek peyniri hangisidir?', 'Gouda', ['Edam', 'Leerdammer', 'Maasdam'], 'Gouda kentinde yüzyıllardır peynir pazarı kurulur; Edam ise kırmızı mum kaplı küre biçimiyle tanınır.'),
  ('İran\'ın Horasan bölgesinde sonbaharda işçiler sabah erkenden mor çiğdem çiçeklerini topluyor ve her çiçekten yalnız üç kırmızı ipliği elle ayırıyor. Elde edilen baharat hangisidir?', 'Safran', ['Vanilya', 'Kakule', 'Karanfil'], 'Safran Crocus sativus çiçeğinden elde edilir; her çiçekte yalnız üç dişicik tepesi bulunduğundan üretimi çok emek ister.'),
  ('Vanilyanın anavatanı ve onu ilk kullanan Totonak ve Aztek halklarının yaşadığı bölge hangisidir?', 'Meksika', ['Madagaskar', 'Endonezya', 'Hindistan'], 'Vanilya orkidesi Meksika kökenlidir; bugün en büyük üretici Madagaskar\'dır ama bitki oraya sonradan götürülmüştür.'),
  ('"Gerçek tarçın" olarak bilinen Cinnamomum verum türünün anavatanı neresidir?', 'Sri Lanka', ['Peru', 'Mısır', 'Madagaskar'], 'Seylan tarçını Sri Lanka\'ya özgüdür; piyasadaki yaygın kasya tarçını ise başka bir türdür.'),
  ('Acı biberin (Capsicum) anavatanı ve Hint, Tay ve Sichuan mutfaklarına ulaşmasından önce yetiştiği kıta hangisidir?', 'Amerika', ['Asya', 'Afrika', 'Avustralya'], 'Acı biber Amerika kökenlidir; 16. yüzyılda Portekiz ve İspanyol denizciler aracılığıyla Asya\'ya yayılmıştır.'),
  ('Hint mutfağında köriye sarı renk veren ve zencefilgiller familyasından bir bitkinin kökünden elde edilen baharat hangisidir?', 'Zerdeçal', ['Kimyon', 'Çörek otu', 'Kişniş'], 'Zerdeçal (Curcuma longa) içerdiği kurkumin sayesinde sarı renk verir.'),
  ('Treviso\'da bir pastanede kahveye batırılmış kedi dili bisküvileri ve mascarpone kremasının katman katman dizildiği, üzerine kakao serpilmiş bir tatlı satılıyor. Bu tatlı hangisidir?', 'Tiramisu', ['Cannoli', 'Panna cotta', 'Zabaglione'], 'Tiramisu "beni yukarı kaldır" anlamına gelir; üstüne kakao serpilir.'),
  ('Madrid\'de gece yarısından sonra bir kafede, uzun yıldız kesitli kızarmış hamur çubukları şekere bulanmış olarak koyu sıcak çikolatayla birlikte servis ediliyor. Bu tatlı hangisidir?', 'Churros', ['Turrón', 'Flan', 'Polvorones'], 'Churros özellikle kahvaltıda ya da gece geç saatlerde koyu sıcak çikolatayla yenir.'),
  ('Japonya\'da yapışkan pirincin dövülmesiyle hazırlanan ve çoğu kez kırmızı fasulye ezmesiyle doldurulan yumuşak tatlı hangisidir?', 'Mochi', ['Dorayaki', 'Taiyaki', 'Castella'], 'Mochi yapışkan pirinç hamurundan yapılır; daifuku denen türü içi anko (tatlı fasulye ezmesi) ile doldurulur.'),
  ('Hindistan\'da süt tozu hamurundan yapılan topların kızartılıp gül suyu ve kakule kokulu şuruba batırıldığı tatlı hangisidir?', 'Gulab jamun', ['Rasgulla', 'Jalebi', 'Ras malai'], 'Gulab jamun adını gül suyundan ve jamun meyvesine benzeyen görünümünden alır.'),
  ('Brezilya\'da doğum günü partilerinin vazgeçilmezi olan, yoğunlaştırılmış süt, kakao ve tereyağıyla yapılıp çikolata granüllerine bulanan küçük toplar hangisidir?', 'Brigadeiro', ['Quindim', 'Pão de queijo', 'Beijinho'], 'Brigadeiro 1940\'larda bir Brezilyalı tuğgeneralin (brigadeiro) adıyla anılmaya başlanmıştır.'),
  ('Avustralya\'da kare pandispanya parçalarının çikolata sosuna batırılıp hindistancevizine bulandığı tatlı hangisidir?', 'Lamington', ['Pavlova', 'Anzac bisküvisi', 'Vegemite'], 'Lamington, adını 19. yüzyıl sonunda Queensland valisi olan Lord Lamington\'dan aldığı kabul edilir.'),
  ('Amritsar\'da sıcak bir günde sokak satıcısı, yoğurdu su ve şekerle köpürene dek çırpıp üzerine bir parça kaymak koyarak toprak bardakta servis ediyor. Bu içecek hangisidir?', 'Lassi', ['Chai', 'Kahwa', 'Sherbet'], 'Lassi tuzlu ya da tatlı yapılabilir; mango lassi en tanınmış türlerindendir.'),
  ('Meksika\'da kurutulmuş hibiskus çiçeği kaliksinin demlenip şekerle tatlandırılmasıyla yapılan koyu kırmızı soğuk içeceğin adı nedir?', 'Agua de Jamaica', ['Horchata', 'Atole', 'Tejuino'], 'Agua de Jamaica kurutulmuş hibiskus kaliksinden demlenir; Batı Afrika\'da benzer içecek bissap ya da sobolo olarak bilinir.'),
  ('Japonya\'da yemek yerken çubukları pirinç kâsesine dik olarak saplamak kaba karşılanır. Bunun nedeni nedir?', 'Cenaze ritüellerinde ölüye sunulan pirinci çağrıştırması', ['Çubukların kırılmasına yol açması', 'Pirincin soğumasını hızlandırması', 'Kâsenin devrilmesine neden olması'], 'Dik saplanmış çubuklar Budist cenaze törenlerinde ölüye sunulan pirinç kâsesini hatırlatır; bu yüzden uğursuz sayılır.'),
  ('Hindistan\'ın bazı bölgelerinde ya da Arap ülkelerinde elle yemek yiyen bir sofrada konuk olan biri yiyeceği hangi eliyle almalıdır?', 'Sağ eliyle', ['Sol eliyle', 'İki eliyle birden', 'Yalnızca çatal ve bıçakla'], 'Birçok Güney Asya ve Orta Doğu kültüründe sol el kişisel temizlikle ilişkilendirilir; yemek sağ elle yenir ve verilir.'),
  ('Fransa\'da sofrada ekmek genellikle tabağa değil, doğrudan masa örtüsünün üzerine konur. Bu alışkanlık Fransız yemek kültürü hakkında ne gösterir?', 'Ekmeğin her öğünde sürekli eşlik eden temel bir öğe olarak görülmesini', ['Ekmeğin yalnızca tatlıyla yenmesini', 'Ekmeğin lüks bir yiyecek sayılmasını', 'Ekmek tabağının yasaklanmasını'], 'Fransa\'da ekmek yemeğin doğal parçasıdır; kişinin yanına, masaya konur ve sosu sıyırmak için kullanılır.'),
  ('Rishikesh\'te bir merkezde katılımcılar her sabah beden duruşları (asana), nefes çalışmaları ve meditasyondan oluşan, kökeni Hindistan\'a dayanan bir uygulamaya katılıyor. Bu uygulama hangisidir?', 'Yoga', ['Ayurveda', 'Kathakali', 'Kalaripayattu'], 'Yoga beden ve zihin bütünlüğünü amaçlar; 2016\'da UNESCO somut olmayan miras listesine alınmıştır.'),
  ('Jamaika\'ya özgü olup 2018\'de UNESCO listesine alınan müzik türü hangisidir?', 'Reggae', ['Calypso', 'Salsa', 'Merengue'], 'Reggae 1960\'ların sonunda Jamaika\'da gelişmiş; Bob Marley ile dünyaca tanınmıştır.'),
  ('Buenos Aires\'in La Boca semtinde bir çift, bandoneonun hüzünlü melodisi eşliğinde yakın tutuşla, keskin bacak hareketleri yaparak dans ediyor. Bu dans hangisidir?', 'Tango', ['Samba', 'Flamenko', 'Salsa'], 'Tango Río de la Plata bölgesinde göçmen kültürlerinin karışımından doğmuş ve 2009\'da UNESCO listesine alınmıştır.'),
  ('Sevilla\'da bir gece kulübünde bir kadın dansçı topuklarını tahta zemine sertçe vurarak dans ediyor, yanında gitarist çalıyor ve bir şarkıcı derin, acılı bir sesle söylüyor. İzlenen sanat hangisidir?', 'Flamenko', ['Fado', 'Muiñeira', 'Jota'], 'Flamenko Endülüs\'te Roman, Arap, Yahudi ve İspanyol etkilerinin buluşmasından doğmuştur.'),
  ('Salvador\'da bir meydanda iki kişi daire biçiminde dizilmiş kalabalığın ortasında, tek telli bir yay çalgısının ritmiyle tekmeler ve akrobatik dönüşlerle hem dövüşüyor hem dans ediyor. Bu uygulama hangisidir?', 'Capoeira', ['Samba', 'Forró', 'Maculelê dansı'], 'Capoeira bir dövüş sanatını dans görünümünde gizleyerek geliştirmiştir; 2014\'te UNESCO listesine alınmıştır.'),
  ('Honolulu\'da bir gösteride çim etekli dansçılar, bir şarkının sözlerindeki dalgaları, yağmuru ve çiçekleri el ve kalça hareketleriyle anlatıyor. Bu dans hangisidir?', 'Hula', ['Haka', 'Siva', 'Tamure'], 'Hula\'da her hareket bir sözcüğü ya da imgeyi temsil eder; hem kutsal hem eğlence amaçlı yapılır.'),
  ('Endonezya\'nın Cava ve Bali adalarında gong, metalofon ve davullardan oluşan geleneksel çalgı topluluğuna ne ad verilir?', 'Gamelan', ['Sitar', 'Shamisen', 'Mbira'], 'Gamelan topluluğu bronz vurmalı çalgılardan oluşur; 2021\'de UNESCO listesine alınmıştır.'),
  ('Paskalya sabahı Londra\'da bir çocuk bahçede saklanmış çikolata yumurtaları arıyor; ebeveynleri bunları uzun kulaklı bir hayvanın getirdiğini söylüyor. Bu figür hangisidir?', 'Paskalya tavşanı', ['Paskalya kuzusu', 'Paskalya horozu', 'Paskalya karatavuğu'], 'Paskalya tavşanı geleneği Almanya\'dan yayılmıştır; tavşan doğurganlık ve ilkbaharı simgeler.'),
  ('İngiltere\'de sonbaharda yapılan, köy halkının son demet tahılı kutlayıp kiliselerde ürün sergilediği geleneksel bayram hangisidir?', 'Harvest Festival', ['Bonfire Night', 'May Day', 'Boxing Day kutlaması'], 'Harvest Festival, eylül sonundaki dolunay (Harvest Moon) yakınında kutlanırdı; okullarda ve kiliselerde yiyecek bağışlanır.'),
  ('Hindistan\'da Dussehra\'da (Vijayadashami) iblis kral Ravana\'nın dev kuklaları yakılır. Bu, hangi destandaki zaferi anar?', 'Ramayana', ['Mahabharata', 'Gılgamış', 'Şehname'], 'Dussehra, Ramayana\'da Rama\'nın Ravana\'yı yenmesini kutlar; iyiliğin kötülüğe zaferini simgeler.'),
  ('Meksika\'da Ölüler Günü\'nde yapılan, üzeri kemik biçimli hamur süsleriyle donatılmış tatlı ekmeğe ne ad verilir?', 'Pan de muerto', ['Rosca de reyes', 'Concha', 'Tres leches'], 'Pan de muerto genellikle portakal çiçeği aromalıdır; sunaklara konur ve aileler tarafından yenir.'),
  ('Berlin\'de bir büfe, dilimlenmiş haşlanmış-kızartılmış sosisin üzerine köri tozu serpilmiş ketçaplı bir sos döküp patates kızartmasıyla veriyor. Bu sokak yemeği hangisidir?', 'Currywurst', ['Bratwurst', 'Leberkäse sandviçi', 'Döner'], 'Currywurst\'ü Herta Heuwer\'in İngiliz askerlerinden edindiği köri tozuyla geliştirdiği anlatılır.'),
  ('Kalküta\'da akşamüstü çay saatinde bir satıcı, içi patates, bezelye ve baharatla dolu, üçgen biçimli çıtır hamur işlerini kızgın yağdan çıkarıp acılı sosla satıyor. Bu yiyecek hangisidir?', 'Samosa', ['Pakora', 'Vada pav', 'Pani puri'], 'Samosa Orta Asya kökenli sambusa geleneğinden gelir; Hindistan\'da genellikle vejetaryendir.'),
  ('Sicilya\'da risotto pirincinin içine ragù ya da peynir konup topa çevrildikten sonra ekmek kırıntısına bulanıp kızartıldığı atıştırmalık hangisidir?', 'Arancini', ['Bruschetta', 'Grissini', 'Supplì'], 'Arancini adı "küçük portakallar" anlamına gelir; Roma\'daki benzerine supplì denir.'),
  ('Japonya\'nın Osaka kentiyle özdeşleşen, ahtapot parçaları içeren ve özel bir kalıpta top biçiminde pişirilen sokak yemeği hangisidir?', 'Takoyaki', ['Yakisoba eriştesi', 'Taiyaki', 'Dango'], 'Takoyaki 1930\'larda Osaka\'da ortaya çıkmıştır; üzerine sos, mayonez ve palamut talaşı konur.'),
  ('Salta\'da bir pazar yerinde, yarım ay biçiminde katlanıp kenarları örgü gibi kıvrılmış, içi kıyma ve soğanla doldurulmuş fırın hamur işleri satılıyor. Bu yiyecek hangisidir?', 'Empanada', ['Quesadilla', 'Burrito', 'Tamale'], 'Empanada "hamura sarılmış" anlamındadır; İspanyol ve Portekiz mutfaklarından Latin Amerika\'ya yayılmıştır.'),
  ('Bir beyzbol maçında seyirciler, uzun yumuşak ekmeğin içine konmuş sıcak sosise hardal ve turşu sosu sürerek yiyor. Bu Amerikan sokak yemeği hangisidir?', 'Hot dog', ['Hamburger', 'Pretzel', 'Bagel'], 'Hot dog, Alman göçmenlerin getirdiği frankfurter sosislerinin ekmek içinde satılmasıyla yaygınlaşmıştır.'),
  ('Japonya\'da fermente soya fasulyesinden yapılan, yapışkan ipliksi dokusu ve keskin kokusuyla bilinen kahvaltılık yiyecek hangisidir?', 'Natto', ['Tempeh', 'Tofu', 'Edamame'], 'Natto Bacillus subtilis bakterisiyle fermente edilir; genellikle pirincin üzerine konarak yenir.'),
  ('Gürcistan\'ın dağ köylerinde bir kadın, karnabahar benzeri beyaz taneleri bir kavanoz süte koyup bir gün bekletiyor ve ekşimsi, hafif köpüklü bir içecek elde ediyor. Bu içecek hangisidir?', 'Kefir', ['Kımız', 'Lassi', 'Kombucha'], 'Kefir taneleri bakteri ve mayaların ortak yaşadığı jelatinimsi kümelerdir; süt içinde fermantasyonu başlatır.'),
  ('Bir ev mutfağında şekerli siyah çayın içine kaygan, disk biçimli bir bakteri-maya tabakası konuyor ve kavanoz bir hafta bekletilince hafif ekşi, köpüklü bir içecek oluşuyor. Bu içecek hangisidir?', 'Kombucha', ['Kefir', 'Kvas', 'Ayran'], 'Kombucha\'da çay ve şeker, bakteri-maya kültürüyle birkaç günde hafif ekşi ve köpüklü bir içeceğe dönüşür.'),
  ('Dünyadaki pirinç türleri arasında Hindistan ve Pakistan\'ın Himalaya eteklerinde yetişen, uzun taneli ve kokulu olanı hangisidir?', 'Basmati', ['Arborio', 'Japonika', 'Bomba'], 'Basmati "kokulu" anlamına gelir; Arborio İtalyan risotto, Bomba İspanyol paella, Jasmine ise Tayland pirincidir.'),
  ('Bugün İtalyan mutfağının ayrılmaz parçası olan domatesin anavatanı hangi kıtadır?', 'Güney ve Orta Amerika', ['Akdeniz kıyıları ve Güney İtalya', 'Güneydoğu Asya', 'Doğu Afrika'], 'Domates And bölgesinde yabani olarak yetişir, Mezoamerika\'da evcilleştirilmiş ve 16. yüzyılda Avrupa\'ya taşınmıştır.'),
  ('Patatesin ilk evcilleştirildiği bölge hangisidir?', 'And Dağları', ['Kuzey Avrupa ovaları', 'Hindistan alt kıtasının kuzey ovaları', 'Kuzey Afrika'], 'Patates yaklaşık 7-10 bin yıl önce Titicaca Gölü çevresinde evcilleştirilmiştir.'),
  ('Çikolatanın hammaddesi olan kakaonun ilk kullanıldığı ve Aztekler ile Mayaların acı bir içecek olarak tükettiği bölge hangisidir?', 'Mezoamerika', ['Batı Afrika', 'Güneydoğu Asya', 'Akdeniz havzası'], 'Kakao Mezoamerika\'da içecek olarak tüketilirdi; çekirdekleri para yerine de kullanılırdı. Bugün en büyük üreticiler Batı Afrika\'dadır.'),
  ('Bugün Kuzey Amerika\'nın simgesi olan hindinin evcilleştirildiği yer neresidir?', 'Meksika', ['Türkiye', 'Hindistan', 'İspanya'], 'Hindi Mezoamerika\'da evcilleştirilmiştir; İngilizce "turkey" adı Avrupalıların onu gine tavuğuyla karıştırmasıyla ilgilidir.'),
  ('Hindistan ve Nepal\'de avuçlar göğüs hizasında birleştirilip hafifçe eğilerek yapılan selamlaşmaya ne ad verilir?', 'Namaste', ['Wai', 'Ojigi', 'Hongi'], 'Namaste "içindeki kutsala selam olsun" anlamına gelir; Tayland\'daki benzer selama wai denir.'),
  ('Tokyo\'da bir mağazaya giren müşteriyi karşılayan çalışan, belini bükerek başını öne doğru eğiyor ve birkaç saniye bu duruşta kalıyor. Bu selamlaşma biçiminin Japonca adı nedir?', 'Ojigi', ['Namaste', 'Hongi', 'Meishi'], 'Ojigi\'de eğilmenin derinliği ve süresi saygı derecesini gösterir; özür ve teşekkürde daha derin eğilinir.'),
  ('Japonya\'da bir eve misafirliğe giden kişi eşikteki genkan denen alanda ne yapmalıdır?', 'Ayakkabılarını çıkarmalıdır', ['Ellerini çırpmalıdır', 'Şapkasını takmalıdır', 'Ev sahibine kapıda küçük bir miktar para vermelidir'], 'Japon evlerinde genkan\'da ayakkabılar çıkarılır; içeride terlik giyilir, tatami üzerinde ise terlik de çıkarılır.'),
  ('Japonya\'da bir onsen (kaplıca) havuzuna girmeden önce bir ziyaretçinin uyması beklenen temel kural hangisidir?', 'Duş alanında iyice yıkanmak', ['Mayo giyip girmek', 'Havlusunu havuzun suyuna batırıp ıslatmak', 'Havuzda sabunla yıkanmak'], 'Onsende ortak suyu temiz tutmak için önce oturarak duş alınır; havlu suya sokulmaz ve genellikle mayo giyilmez.'),
  ('Hindistan\'da tek bir büyük tepside küçük kâselerde pek çok farklı yemeğin bir arada sunulduğu öğün düzenine ne ad verilir?', 'Thali', ['Tiffin', 'Tandoor', 'Tadka'], 'Thali\'de pilav, dal, sebze, yoğurt, ekmek ve tatlı gibi farklı tatlar bir arada bulunur.'),
  ('Montevideo\'da bir anneanne sütü ve şekeri saatlerce kısık ateşte karıştırarak koyu kahverengi, kremamsı bir sos elde ediyor; bunu alfajor kurabiyelerinin arasına sürecek. Bu sos hangisidir?', 'Dulce de leche', ['Crema catalana', 'Arroz con leche', 'Tres leches'], 'Dulce de leche alfajor kurabiyelerinde ve pek çok tatlıda kullanılır.'),
  ('New Orleans\'ta Mardi Gras döneminde yenen, içine küçük bir bebek figürü saklanan ve mor, yeşil, altın rengi şekerle süslenen kek hangisidir?', 'King cake', ['Pecan pie', 'Beignet', 'Bread pudding'], 'King cake\'te bebeği bulan kişinin bir sonraki partiyi düzenleyeceği ya da keki getireceği kabul edilir.'),
  ('Sevilla\'da Paskalya\'dan önceki haftada kukuletalı tövbekârların ve dev dinî heykellerin (paso) sokaklarda taşındığı tören haftasının adı nedir?', 'Semana Santa', ['Feria de Abril', 'La Mercè', 'Fallas'], 'Semana Santa (Kutsal Hafta) İspanya\'nın pek çok kentinde dinî alaylarla geçer; Sevilla\'daki en ünlüleridir.'),
  ('Almanya\'da öğleden sonra ailelerin bir araya gelip pasta ve kahve eşliğinde oturduğu geleneğe ne denir?', 'Kaffee und Kuchen', ['Abendbrot', 'Brotzeit', 'Frühschoppen'], 'Kaffee und Kuchen özellikle pazar öğleden sonraları yaygındır; Abendbrot ise ekmek, peynir ve şarküteriden oluşan sade akşam yemeğidir.'),
  ('Budapeşte\'de bir çorbacıda sığır eti, patates ve havucun bolca toz kırmızı biberle kazanda pişirildiği kırmızı renkli bir çorba servis ediliyor. Bu yemek hangisidir?', 'Gulyás', ['Lángos', 'Pörkölt', 'Dobos torta'], 'Gulyás (gulaş) aslen Macar çobanlarının kazanda pişirdiği yemektir; pörkölt daha koyu kıvamlı bir yahnidir.'),
  ('Gürcistan mutfağının tanınmış yemeklerinden olan, peynirle doldurulmuş, kayık biçimli olanının ortasına yumurta kırılan ekmek hangisidir?', 'Haçapuri', ['Hinkali', 'Lobio', 'Çurçhela'], 'Acar usulü haçapuri kayık biçimindedir; hinkali ise suyu içinde kalan iri bir mantıdır.'),
  ('İran\'daki Şeb-i Yelda, İskandinavya\'daki Jul ve Çin\'deki Dongzhi bayramlarının ortak teması nedir?', 'Kış gündönümünde günlerin yeniden uzamaya başlamasının kutlanması', ['Bahar ekinoksunda ekim yapılması', 'Yaz gündönümünde şenlik ateşleri yakılıp ateşin üzerinden atlanması', 'Hasadın sonbaharda toplanması'], 'Üç bayram da yılın en uzun gecesine yakın kutlanır ve ışığın geri dönüşünü simgeler; Dongzhi\'de tangyuan yenir.'),
  ('Avustralya\'da Noel neden çoğunlukla plajda ya da mangal başında kutlanır?', 'Güney Yarımküre\'de olduğu için Noel\'in yaz aylarına denk gelmesi', ['Avustralya\'da Noel\'in aralık yerine temmuz ayının ortasında kutlanması', 'Kışın plajların ısıtılması', 'Noel\'in Avustralya\'da resmî tatil olmaması'], 'Aralık Güney Yarımküre\'de yaz mevsimidir; bu yüzden Noel sofraları çoğu kez açık havada, deniz ürünleri ve mangalla kurulur.'),
  ('Avustralya\'da maya özütünden yapılan, koyu renkli, tuzlu ve ekmeğe ince sürülerek yenen ezme hangisidir?', 'Vegemite', ['Marmite', 'Nutella', 'Fıstık ezmesi'], 'Vegemite 1922\'de Melbourne\'da üretilmeye başlanmıştır; İngiliz Marmite\'ı da benzer bir maya özütü ezmesidir.'),
  ('Hawaii\'de bütün bir domuzun yer fırınında pişirildiği, hula ve müzikle eşlik edilen geleneksel ziyafete ne denir?', 'Luau', ['Imu', 'Poke', 'Haka'], 'Luau adını bu şölenlerde yapılan taro yapraklı yemekten alır; imu ise yer fırınının adıdır.'),
  ('Meksika\'da 6 Ocak\'ta (Día de Reyes) kesilen, içinde bebek İsa figürü saklanan halka biçimli tatlı ekmeğin adı nedir?', 'Rosca de Reyes', ['Pan de muerto', 'Tres leches', 'Churros con chocolate'], 'Figürü bulan kişi 2 Şubat\'ta (Candelaria) herkese tamales ikram eder.'),
  ('Brezilya\'da manyok unu ve peynirle yapılan, glutensiz küçük peynirli ekmek topları hangisidir?', 'Pão de queijo', ['Feijoada', 'Farofa', 'Coxinha'], 'Pão de queijo Minas Gerais eyaletinden çıkmıştır; manyok nişastası ona esnek ve çiğnenebilir bir doku verir.'),
  ('Meksika\'nın Puebla kentinde 1862\'deki bir zaferi anan ve ABD\'de daha yaygın kutlanan gün hangisidir?', 'Cinco de Mayo', ['Día de los Muertos', 'Día de la Independencia', 'Día de Reyes'], 'Cinco de Mayo, 5 Mayıs 1862\'deki Puebla Savaşı\'nda Meksika ordusunun Fransızları yenmesini anar; Meksika\'nın bağımsızlık günü ise 16 Eylül\'dür.'),
  ('Almanya ve Avusturya\'da Advent döneminde yapılan, şekerlenmiş meyveli, üzeri pudra şekerli uzun Noel çöreğinin adı nedir?', 'Stollen', ['Lebkuchen', 'Strudel', 'Spekulatius'], 'Dresden Christstollen en ünlü türüdür; şekli kundaklanmış bebek İsa\'yı simgeler.'),
  ('Hindistan\'ın kuzeydoğusundaki Batı Bengal eyaletinde Himalaya eteklerinde yetişen ve "çayların şampanyası" olarak anılan siyah çay hangisidir?', 'Darjeeling', ['Assam', 'Seylan', 'Nilgiri'], 'Darjeeling çayı yüksek rakımda yetişir; Assam ise ovada yetişen, daha sert ve maltımsı bir çaydır.'),
  ('Bir Milano kafesinde sabah kahvaltısında espresso, sıcak süt ve üzerinde kalın bir süt köpüğü katmanından oluşan bir kahve, kruvasanla birlikte servis ediliyor. Bu kahve hangisidir?', 'Cappuccino', ['Ristretto', 'Affogato', 'Lungo'], 'Cappuccino adını Kapuçin keşişlerinin cübbe rengine benzemesinden alır.'),
  ('Viyana\'da bir pastanede gazete okunabilecek kadar ince açılmış hamura elma, tarçın ve kuru üzüm sarılarak fırınlanmış, üzerine pudra şekeri serpilmiş bir tatlı satılıyor. Bu tatlı hangisidir?', 'Apfelstrudel', ['Sachertorte', 'Kaiserschmarrn', 'Linzer torte'], 'Apfelstrudel Viyana mutfağının simgelerindendir; hamurun gazete okunabilecek kadar ince açılması gerektiği söylenir.'),
];
